function styleRange(el){el.style.setProperty('--value',`${(el.value-el.min)/(el.max-el.min)*100}%`);}
function syncSimulationResponse(){const slider=$('#responseSpeed'),n=clamp(Math.round(state.simulationResponse||0),-20,20);slider.value=String(n);styleRange(slider);const mult=responseMultiplier(n),digits=n===0||n===20?0:n===-20?2:mult<.1?3:2;const text=fmt(mult,digits);$('#responseSpeedOutput').textContent=`${text}×`;slider.setAttribute('aria-valuetext',`${text} volte`);}
