if(!headsailInhaulAllowed(state)&&state.controls.genoa.barber<50){state.controls.genoa.barber=50;if(!controlEnabled(state,'genoa','barber'))state.fixedControls['genoa.barber']=50;}const boat=boatProfile(state),cert=isCertificateBoat(state),head=headsailInfo(state),fore=state.foresail!=='none';names.genoa=head.name;if(!fore&&controlTab!=='main')controlTab='main';
