 const active=[...(state.main?['Randa']:[]),...(fore?[names[state.foresail]+(state.foresail==='genoa'&&!cert&&!state.sailDesigns.genoa.exploratory?' '+state.genoaSize+'%':'')]:[])];$('#planSummary').textContent=active.join(' + ')||'Nessuna vela issata';$('#sailCount').textContent=`${active.length} ${active.length===1?'vela attiva':'vele attive'}`;$('#sailSelectionSize').classList.toggle('hidden',!fore||(state.foresail==='genoa'&&(cert||!!state.sailDesigns.genoa.exploratory)));$('#planTrimShortcut').disabled=!active.length;
