function showMeasureWarnings(){const m=editableDesign(designType,state),warnings=m.exploratory?designWarnings(designType,m,state):{};for(const [key] of MEASURE_FIELDS[designType]){const row=$('#measure-'+key)?.closest('.measure-row');if(!row)continue;const messages=[...new Set(warnings[key]||[])];row.classList.toggle('unreasonable',!!messages.length);row.querySelector('.measure-warning').textContent=messages.join(' ');for(const input of row.querySelectorAll('input'))input.setAttribute('aria-invalid',String(!!messages.length));}const count=Object.keys(warnings).length;$('#designWarningSummary').textContent=count?'Misure fuori proporzione: valori accettati, ricostruzione e prestazioni indicative.':'';$('#designWarningSummary').classList.toggle('hidden',!count);}

