 const twistRow=staticTwist?`<div class="measure-row measure-twist-row"><label for="measure-twist"><span>${t('Svergolamento diretto','Direct twist')} <small>°</small></span><input id="measure-twist" data-static-twist type="number" min="0" max="50" step="1" value="${twistValue}" inputmode="numeric" aria-describedby="measure-twist-help"></label><input id="measure-twist-range" data-static-twist type="range" min="0" max="50" step="1" value="${twistValue}" aria-label="${t('Svergolamento diretto in gradi','Direct twist in degrees')}" aria-describedby="measure-twist-help"><small id="measure-twist-help">${t('10° di default · 0° alla base, valore impostato in penna; rotazione proporzionale lungo l’altezza.','10° default · 0° at the foot, selected angle at the head; proportional rotation over the height.')}</small></div>`:'';
