$$('[data-pick-boat]').forEach(button=>button.addEventListener('click',()=>windows.toggleInfo('boat',boatPicker)));
function changeControlEnabled(id,enabled){const [category,key]=id.split('.'),focused=document.activeElement?.dataset?.controlEnabled===id;cancelSingleAuto();clearTimeout(autoTimer);clearTimeout(initialReferenceTimer);++workerJob;solverWorker?.terminate();workerBusy=false;setControlEnabled(state,category,key,enabled);autoReport=null;autoCarTarget=null;renderControls();if(focused)$(`[data-control-enabled="${id}"]`)?.focus({preventScroll:true});updateImmediate();syncAuto();if(state.auto)autoTimer=setTimeout(()=>requestOptimization(true),80);}
function manual(){cancelSingleAuto();autoReport=null;autoCarTarget=null;if(state.auto){clearTimeout(initialReferenceTimer);clearTimeout(autoTimer);++workerJob;solverWorker?.terminate();workerBusy=false;solverPercent=0;solverProgress({progress:0,phase:'queued'});autoTimer=setTimeout(()=>requestOptimization(true),300);}}
function syncAuto(){
 if(workerBusy&&(state.auto||singleAutoJob)){renderAutoProgress();return;}
 $('#autoButton').setAttribute('aria-busy','false');$('#autoButton').setAttribute('aria-pressed',state.auto);syncHeaderAuto();$('#autoButton>span').textContent=state.auto?'Assetto automatico attivo':'Assetto automatico';$('#autoButton small').textContent=state.auto?'ON':'AUTO';
 if(!hasCertifiedPolar(state)){
  $('#autoDescription').textContent=!state.auto?t('Ottimizza le manovre abilitate per velocità e flusso. Conserva vele e vincoli.','Optimize enabled controls for speed and airflow. Keep sails and fixed controls.'):autoReport?.constraintsFeasible===false?t('Vincoli incompatibili: libera una manovra o modifica il taglio.','Incompatible constraints: unlock a control or change the sail cut.'):autoLiveConstraintBlocked?t('Carrello fissato: verifica il rinvio durante l’assestamento della vela.','Fixed car: check the lead while the sail settles.'):!autoReport?t('Ricerca di velocità e flusso per le vele scelte.','Searching for speed and flow with the selected sails.'):autoReport.flowReached?t('Assetto trovato con flusso coerente con l’andatura.','Trim found with airflow appropriate to the course.'):t('Miglior compromesso stimato fra velocità e flusso.','Best estimated compromise between speed and airflow.');
  return;
 }
 $('#autoDescription').textContent=!state.auto?'Ottimizza le manovre abilitate verso il 100% della polare. Conserva vele e vincoli; valuta aderenza in bolina ed esposizione/stabilità in poppa.':autoReport?.constraintsFeasible===false?'Vincoli incompatibili: libera una manovra o modifica il taglio. I valori fissati sono conservati.':autoLiveConstraintBlocked?'Carrello fissato: verifica il rinvio durante l’assestamento della vela.':!autoReport?'Ricerca di velocità e flusso per le vele scelte.':autoReport.targetReached?(autoReport.flowReached?'Target di polare e assetto del flusso coerente con l’andatura.':'Target di polare raggiunto; resta separazione su alcune sezioni.'):autoReport.flowReached?'Flusso coerente con l’andatura; il piano scelto o i vincoli limitano il target.':'Miglior compromesso trovato fra target e flusso per queste vele e vincoli.';
}

function syncHeaderAuto(){const busy=workerBusy&&(state.auto||!!singleAutoJob),button=$('#headerAutoButton');button.setAttribute('aria-pressed',String(state.auto));button.setAttribute('aria-busy',String(busy));button.classList.toggle('active',state.auto);$('#headerAutoProgress').textContent=busy?`${solverPercent}%`:state.auto?(autoReport?'100%':'ON'):'OFF';button.title=(getLanguage()==='en'?'Continuous AUTO: recalculates wind, sail and trim changes. Keeps selected sails and fixed controls.':'AUTO continuo: ricalcola dopo modifiche a vento, vele e manovre. Conserva vele e vincoli.')+(busy?' · '+phaseLabel(solverPhase):'');}
function phaseLabel(phase){if(!hasCertifiedPolar(state)&&phase==='reference')return t('Riferimento del modello','Model reference');if(!hasCertifiedPolar(state)&&phase==='match')return t('Convergenza delle forze','Force convergence');const names={queued:['In attesa delle modifiche','Waiting for edits'],reference:['Riferimento polare','Polar reference'],inventory:['Ricerca delle manovre','Trim search'],flow:['Equilibrio e segnavento','Equilibrium and telltales'],match:['Convergenza alla polare','Polar convergence'],validate:['Verifica finale','Final verification']};return (names[phase]||names.inventory)[getLanguage()==='en'?1:0];}
function renderAutoProgress(){if(!state.auto&&!singleAutoJob){syncAuto();return;}$('#autoButton').setAttribute('aria-busy','true');$('#autoButton').setAttribute('aria-pressed',String(state.auto));$('#autoButton>span').textContent=state.auto?'Ricerca assetto…':'Assetto automatico';$('#autoButton small').textContent=`${solverPercent}%`;$('#autoDescription').textContent=phaseLabel(solverPhase);syncHeaderAuto();}
function solverProgress(message){workerBusy=true;solverPercent=Math.max(solverPercent,Math.min(99,Math.round((message.progress||0)*100)));solverPhase=message.phase||solverPhase;renderAutoProgress();}

function finishOptimization(message,id,applyAuto){if(id!==workerJob||message.reference.key!==referenceKey(state))return;installReference(message.reference);workerBusy=false;$('#autoButton').setAttribute('aria-busy','false');if(applyAuto&&state.auto&&message.solution){const solution=message.solution;shapeComparison={id:'auto',time:performance.now(),before:Object.fromEntries(['main',state.foresail].filter(t=>t!=='none').map(t=>[t,shapeSummary(t,state)]))};const previousControls=state.controls;state.controls=structuredClone(solution.state.controls);restoreFixedControls(state);autoCarTarget=state.controls.genoa.car;autoReport=solution;controlTab=controlTab==='main'?'main':state.foresail;updatePlan();renderControls();scene?.highlightAffected(Object.entries(CONTROL_DEFS).flatMap(([c,defs])=>defs.filter(d=>controlEnabled(state,c,d[0])&&Math.abs(previousControls[c][d[0]]-state.controls[c][d[0]])>.001).map(d=>`${c}.${d[0]}`)));toast(!hasCertifiedPolar(state)?(solution.constraintsFeasible===false?'Vincoli incompatibili: i valori fissati restano invariati.':solution.flowReached?'Assetto e flusso ottimizzati per le vele selezionate.':'Miglior assetto stimato per le vele selezionate.'):solution.constraintsFeasible===false?'Vincoli incompatibili: i valori fissati restano invariati.':solution.targetReached?(solution.flowReached?'Target di polare e assetto del flusso coerente con l’andatura.':'Target di polare raggiunto; resta separazione su alcune sezioni.'):`Miglior equilibrio trovato: ${fmt(solution.achievable)}% della polare con queste vele.`);}syncAuto();updateImmediate();persistence?.schedule();}
function requestOptimization(applyAuto=state.auto){cancelSingleAuto();const id=++workerJob,snapshot=structuredClone(state),existing=getReference(state);if(existing&&!applyAuto){workerBusy=false;syncAuto();updateImmediate();return;}workerBusy=true;solverPercent=0;solverPhase='reference';solverProgress({progress:0,phase:'reference'});if(solverWorker)solverWorker.terminate();
 if(typeof Worker!=='undefined'){try{solverWorker=new Worker(new URL('./trim-worker.js',import.meta.url),{type:'module'});solverWorker.onmessage=e=>{const m=e.data;if(m.id!==workerJob)return;if(m.type==='progress')solverProgress(m);else if(m.type==='result')finishOptimization(m,id,applyAuto);else{workerBusy=false;syncAuto();toast('Ricerca interrotta: '+m.message);}};solverWorker.onerror=()=>{if(id!==workerJob)return;workerBusy=false;syncAuto();toast('La ricerca numerica non è stata completata.');};solverWorker.postMessage({id,state:snapshot,applyAuto,reference:existing});return;}catch(error){solverWorker=null;}}
 // Same solver as a fallback in browsers without module workers.
 setTimeout(()=>{if(id!==workerJob)return;try{const progress=p=>solverProgress(p),reference=existing||computeReference(snapshot,p=>progress({...p,phase:'reference',progress:p.progress*(applyAuto?.35:1)})),solution=applyAuto?optimizeForReference(snapshot,reference,p=>progress({...p,progress:(existing?0:.35)+p.progress*(existing?1:.65)})):null;finishOptimization({reference,solution},id,applyAuto);}catch(error){workerBusy=false;syncAuto();toast(error.message);}},20);
}
function runAuto(){autoCarTarget=null;keepAutoCarBehindClew();clearTimeout(initialReferenceTimer);clearTimeout(autoTimer);requestOptimization(state.auto);}
function onWindChange(){windResponseRemaining=3;cancelSingleAuto();autoReport=null;shapeComparison=null;clearTimeout(initialReferenceTimer);clearTimeout(autoTimer);++workerJob;solverWorker?.terminate();workerBusy=false;if(state.auto){solverPercent=0;solverProgress({progress:0,phase:'queued'});}updatePlan();updateImmediate();autoTimer=setTimeout(()=>requestOptimization(state.auto),220);}
function apparentAngleLabel(angle){const a=Math.abs(angle);return `${fmt(a,0)}°${a<.5||a>179.5?'':getLanguage()==='en'?(angle>0?' STB':' PORT'):(angle>0?' DX':' SX')}`;}
function syncApparentAngle(){const awa=apparentWind(state.windSpeed,state.windAngle,speed).angle,side=awa===0||Math.abs(awa)===180?'':getLanguage()==='en'?(awa>0?'STB':'PORT'):(awa>0?'DX':'SX');for(const id of ['windAwaValue','windAwaOutput','headerApparentDirection'])$('#'+id).textContent=`${fmt(Math.abs(awa),0)}°`;$('#headerApparentSide').textContent=side;$('#instrumentAwa').textContent=apparentAngleLabel(awa);$('#windCompact').textContent=`${fmt(state.windSpeed,state.windSpeed%1?1:0)} kn · TWA ${Math.abs(state.windAngle)}° · AWA ${fmt(Math.abs(awa),0)}°`;const quick=$('#quickWindApparent');quick.textContent=`${t('Vento apparente','Apparent wind')} · AWA ${apparentAngleLabel(awa)}`;if($('#windDial'))$('#windDial').setAttribute('aria-valuetext',`${Math.abs(state.windAngle)}° ${t('reale','true')} · ${fmt(Math.abs(awa),0)}° ${t('apparente','apparent')}`);}
