function keepAutoCarBehindClew(){
 if(!state.auto||state.foresail!=='genoa'){autoLiveConstraintBlocked=false;return;}
 const previous=state.controls.genoa.car,blocked=!constrainAutoJibCar(state,autoCarTarget??previous);
 if(blocked)autoCarTarget=null;
 if(blocked!==autoLiveConstraintBlocked){autoLiveConstraintBlocked=blocked;syncAuto();}
 if(Math.abs(previous-state.controls.genoa.car)>.00001)syncControlInputs('genoa','car');
}

function updateImmediate(){trimResponseRemaining=2;state.boatSpeed=speed;advanceJibDynamics(state,0);keepAutoCarBehindClew();metric=evaluate(state,speed);state.rigLoads=metric.rigLoads;state.effectiveSheets=metric.effectiveSheets;updateUI();updateInspector();}
function updateUI(){syncPolarAvailability();updateHeaderTelemetry();syncApparentAngle();graphicsControls?.update();windProfileView?.update();forceControls?.update();updateProfileOverlays();syncDirectControl();const m=metric;$('#boatSpeed').textContent=fmt(speed,2);$('#apparentWind').textContent=fmt(m.aws);$('#awaValue').textContent=`${fmt(Math.abs(m.awa),0)}°`;$('#efficiency').textContent=hasCertifiedPolar(state)?fmt(m.polarEfficiency,0):'—';$('#efficiencyBar').style.width=hasCertifiedPolar(state)?`${clamp(m.polarEfficiency,0,100)}%`:'0%';$('#heelValue').textContent=fmt(m.heel);$('#heelCaption').textContent=m.heel>25?'Barca sovrainvelata':m.heel<5?'Carico leggero':'Carico equilibrato';
 $('#polarTarget').textContent=hasCertifiedPolar(state)?fmt(m.polarTarget,2):'—';
 const noGo=Math.abs(state.windAngle)<30,calm=state.windSpeed<.5;
 $('#speedStatus').textContent=calm?'In attesa di vento':noGo?'Prua al vento':m.efficiency>90?'Assetto in equilibrio':m.efficiency>65?'Regolazione migliorabile':'Flusso da ritrovare';
 let title='Flusso aderente',text='I segnavento scorrono paralleli: la vela lavora bene.';
 if(calm){title='Il vento si è fermato';text='Aumenta l’intensità per mettere in movimento vele e segnavento.';}
 else if(noGo){title='Sei nella zona morta';text='Poggia oltre 35–40°: le vele torneranno a generare spinta.';}
 else if(m.heel>27){title='Riduci il carico';text=isCertificateBoat(state)?'Appiattisci la randa e apri il carrello. Valuta la vela disponibile più adatta.':'Appiattisci la randa, apri il carrello e scegli il fiocco 105%.';}
 else if(!m.sails.length){title='Nessuna vela issata';text='Issa la randa o scegli una vela di prua per riprendere la navigazione.';}
 else if(!m.telltales.appropriate){const sail=m.telltales.sails.reduce((a,b)=>a.loss>b.loss?a:b);title=Math.abs(m.awa)>110?'Flusso alle portanti':`${names[sail.type]} da regolare`;text=Math.abs(m.awa)>110?'In poppa il flusso può separarsi anche nell’assetto migliore. Osserva ogni vela e la superficie esposta.':'Controlla scotta, carrello e svergolamento; confronta i nastri sui due lati della vela.';}
 else if((state.foresail==='spinnaker'&&Math.abs(state.windAngle)<120)||(state.foresail==='gennaker'&&Math.abs(state.windAngle)<75)){title='Scegli una vela più adatta';text=`Questa vela rende meglio a un’andatura più larga. Seleziona ${headsailInfo(state).name.toLowerCase()} per risalire il vento; AUTO ottimizza la vela scelta.`;}
 else if(m.efficiency<90){title='Puoi trovare più equilibrio';text='Regola le scotte e osserva i segnavento lungo l’altezza delle vele.';}
 if(m.telltales.appropriate&&m.telltales.intermittent){title='Filetti a segno';text='Il filetto alto può sventare brevemente: è vicino al distacco. Gli altri restano distesi.';}$('#feedbackTitle').textContent=title;$('#feedbackText').textContent=text;
 $('#vmgValue').textContent=`${fmt(Math.abs(m.vmg))} kn`;$('#leewayValue').textContent=`${fmt(m.leeway)}°`;$('#rudderValue').textContent=`${fmt(m.rudderAngle)}°`;$('#vmgLabel').textContent=Math.abs(state.windAngle)>90?'VMG sottovento':'VMG sopravento';

 updateInspector();
}
const dialog=$('#infoDialog');function showDialog(html){++dialogVersion;dialog.classList.remove('catalog-mode','certificate-mode');$('#dialogContent').innerHTML=html;if(!dialog.hasAttribute('open')){if(dialog.show)dialog.show();else dialog.setAttribute('open','');}windows.anchor(dialog);return dialogVersion;}
